// Fills the explainer from window.SITE (generated by website/build.py) and runs the toys.
(function () {
  const S = window.SITE, P = S.params;
  const pct = v => Math.round(v * 100) + "%";
  const money = v => (+v).toFixed(v >= 10 ? 0 : 2);
  const $ = s => document.querySelector(s);

  // inline parameters
  document.querySelectorAll("[data-p]").forEach(e => {
    const v = P[e.dataset.p];
    e.textContent = e.dataset.fmt === "pct" ? pct(v) : v;
  });
  document.querySelectorAll("[data-world]").forEach(e => { e.textContent = S.world[e.dataset.world]; });
  $("#dil").textContent = (1 + P.DILUTION).toFixed(2);
  $("#dil2").textContent = (1 + P.DILUTION).toFixed(2);
  $("#null-r").textContent = Math.pow((1 + P.INVEST_RATE) / (1 + P.HURDLE), P.Q).toFixed(2);
  $("#vendor-list").textContent = S.world.vendors.map(v => v.name).join(", ");

  // sectors
  const sectors = Object.entries(P.SECTORS).sort((a, b) => b[1].freq - a[1].freq);
  Charts.bars("#chart-sectors", sectors.map(([k, v]) => ({
    label: k.replace("_", " "), value: v.freq, color: "--s1",
    note: `median claim $${v.median}m before the tail; ${Math.round(v.weight * 100)}% of clients`
  })), { format: v => v.toFixed(2) + "/yr", labelName: "Sector", valueName: "Incidents per year", aria: "incidents per year by sector" });

  // dossiers
  const dz = $("#dossiers");
  S.dossiers.forEach(d => {
    const r = d.true_el / d.actuary_el;
    const cls = r > 1.15 ? "ratio-up" : r < 0.87 ? "ratio-down" : "";
    const hidden = [
      `true autonomy ${d.autonomy_true} (signal ${d.autonomy_signal})`,
      `true safety ${d.safety_true} (signal ${d.safety_signal})`,
      d.corner_cutting ? "<b>cuts corners</b>" : "does not cut corners",
      `unknown-unknown ×${d.hidden_mult}`,
      `${d.vendor} quality ×${d.vendor_quality}${d.vendor_stated ? "" : " (vendor undisclosed)"}`
    ].join(" · ");
    const card = document.createElement("div");
    card.className = "dossier";
    card.innerHTML = `<div class="head"><span>${d.label}</span><span>limit $${d.ideal_limit}m</span></div>
      <div class="body">${d.text}</div>
      <div class="truth">Actuary's estimate <b>$${money(d.actuary_el)}m</b>/yr · Truth <b>$${money(d.true_el)}m</b>/yr
        <span class="${cls}">(${r >= 1 ? "×" + r.toFixed(1) : "×" + r.toFixed(2)})</span><br><span style="font-size:13px">${hidden}</span></div>`;
    dz.appendChild(card);
  });

  // reporting lag
  const lags = Object.entries(S.lags.counts).map(([k, v]) => [+k, v]);
  const total = lags.reduce((a, b) => a + b[1], 0);
  Charts.bars("#chart-lag", lags.map(([k, v]) => ({ label: `${k} quarter${k > 1 ? "s" : ""} later`, value: v / total, color: "--s1",
    note: `${v} claims, $${S.lags.amounts[k]}m covered` })), { format: pct, labelName: "Delay", valueName: "Share of claims", aria: "reporting delay" });

  // market cycle with events
  const ev = S.world.events.filter(e => e.kind !== "false_alarm").map((e, i) => ({
    x: e.q + 1, label: { cat: "catastrophe", flaw: "vendor defect", ruling: "ruling", mandate: "mandate", safe_harbour: "safe harbour" }[e.kind] || e.kind, row: i % 3 }));
  Charts.line("#chart-cycle", [{ name: "Premium ÷ true expected loss", color: "--s1", points: S.lags.market.map(m => [m.q + 1, m.adequacy]) }],
    { events: ev, yMin: 0, tipFormat: v => v.toFixed(2) + "×", aria: "market price adequacy" });

  // median R by strategy
  const names = { actuary: "Actuary (reference)", null: "Null: does nothing", reckless: "Reckless", cycle: "Cycle-follower", random: "Random",
                  deny_all: "Actuary that denies every claim", no_reins: "Actuary without reinsurance", timid: "Timid actuary" };
  const med = a => { const s = [...a].sort((x, y) => x - y); const n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
  const rows = Object.entries(S.gallery).map(([k, g]) => ({ k, label: names[k] || k, value: med(g.map(x => x.R)),
    surv: g.filter(x => !x.insolvent).length / g.length })).sort((a, b) => b.value - a.value);
  Charts.bars("#chart-scores", rows.map(r => ({ label: r.label, value: r.value, color: r.k === "actuary" ? "--s1" : "--s7",
    note: `survived ${pct(r.surv)} of seeds`, suffix: `  (${pct(r.surv)} survive)` })),
    { format: v => v.toFixed(2), labelWidth: 250, labelName: "Strategy", valueName: "Median R", aria: "median R by strategy" });
  // reference line at R = 1
  const svg = $("#chart-scores svg");
  if (svg) {
    const max = Math.max(...rows.map(r => r.value)), lw = 250, W = 720;
    const x = lw + 1 / max * (W - lw - 90);
    const ns = "http://www.w3.org/2000/svg";
    const l = document.createElementNS(ns, "line");
    Object.entries({ x1: x, x2: x, y1: 0, y2: rows.length * 34 + 8, stroke: "var(--ink-2)", "stroke-width": 1, "stroke-dasharray": "3 3" }).forEach(([a, b]) => l.setAttribute(a, b));
    svg.appendChild(l);
  }

  // cast
  const cast = [
    ["Actuary", "Reference and rival", "Prices at its estimate of expected loss plus a catastrophe load and a margin; learns a correction per sector from its own claims; books IBNR; settles murky claims; buys exactly the reinsurance the single-risk rule needs; raises capital when restricted; pays out surplus capital each year."],
    ["Predator", "Rival", "The actuary, except that when it is healthy and a rival looks weak it cuts prices by 15% to finish them off."],
    ["Reckless", "Rival", "Undercuts the market by 10%, never books IBNR, denies murky claims, buys no reinsurance, pays out half of each year's reported profit."],
    ["Cycle-follower", "Rival", "Prices halfway between last quarter's market rate and its own estimate. Pays every claim. Wins the clients everyone else priced higher."],
    ["Random", "Test strategy", "Prices at its estimate times a random factor, and makes random claim decisions. The floor of competence."],
    ["Null", "Test strategy", "Writes nothing. Its cash earns 1% a quarter against a 2% hurdle, so it scores " + Math.pow((1 + P.INVEST_RATE) / (1 + P.HURDLE), P.Q).toFixed(2) + "."],
    ["Shortcut probes", "Test strategies", "The actuary with one thing changed: deny every claim, contest every claim, pay every claim, no reinsurance, margin up or down ten points, quote only a quarter of applicants. None may beat the reference."],
  ];
  const cz = $("#cast");
  cast.forEach(([n, t, d]) => { const c = document.createElement("div"); c.className = "card"; c.innerHTML = `<span class="tag">${t}</span><h4>${n}</h4><p>${d}</p>`; cz.appendChild(c); });

  // interface
  $("#brief-q").textContent = S.briefing.quarter;
  $("#briefing").textContent = S.briefing.briefing;
  $("#system").textContent = S.briefing.system;
  const tb = $("#tools tbody");
  S.briefing.tools.forEach(t => { const r = document.createElement("tr"); r.innerHTML = `<td><code>${t.name}</code></td><td>${t.description}</td>`; tb.appendChild(r); });

  // ---------------- transcripts: one real quarter per model
  (function () {
    const turns = S.turns || [];
    const tabs = $("#turn-tabs"), body = $("#turn-body");
    $("#turn-env").textContent = turns.length ? turns[0].env_version : "";
    if (!turns.length) { body.innerHTML = "<p><i>No language-model games were available when this page was built.</i></p>"; return; }
    const esc = t => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;");
    const pretty = v => esc(typeof v === "string" ? v : JSON.stringify(v, null, 2));
    const what = { get_applicants: "reads a page of applicants", submit_quotes: "quotes premiums", set_rate_manual: "sets its standing price table",
      decline: "turns applicants away", decide_claims: "decides claims", set_ibnr: "sets the reserve for unreported claims",
      pay_dividend: "pays shareholders", raise_capital: "asks shareholders for money", set_reinsurance: "chooses reinsurance",
      predict_loss_ratio: "forecasts its loss ratio", write_notes: "writes notes for next quarter", board_memo: "writes to the board",
      end_turn: "ends the quarter" };
    function show(i) {
      const t = turns[i];
      [...tabs.children].forEach((b, j) => b.setAttribute("aria-selected", j === i ? "true" : "false"));
      const pos = t.position;
      body.innerHTML = `<div class="turn-head">
          <span class="pill">${esc(t.model)}</span><span class="pill">seed ${t.seed}</span><span class="pill">quarter ${t.quarter} of 40</span>
          <span class="pill">audited equity $${(pos.audited_equity ?? pos.reported_equity).toFixed(1)}m</span>
          <span class="pill">${pos.policies_in_force} policies in force</span></div>
        <ol class="calls">${t.calls.map(c => `<li><div class="call tool-${c.tool}">
          <div class="name">${esc(c.tool)}<span>${what[c.tool] || ""}</span></div>
          ${c.input && Object.keys(c.input).length ? `<pre>${pretty(c.input)}</pre>` : `<pre style="color:var(--muted)">(no arguments)</pre>`}
          <details${c.tool === "end_turn" ? " open" : ""}><summary>The game replied</summary><pre>${pretty(c.output)}</pre></details>
        </div></li>`).join("")}</ol>`;
    }
    turns.forEach((t, i) => {
      const b = document.createElement("button");
      b.type = "button"; b.setAttribute("role", "tab"); b.textContent = t.model.replace(/^.*\//, "");
      b.addEventListener("click", () => show(i));
      tabs.appendChild(b);
    });
    show(0);
  })();

  // ---------------- toy: winner's curse
  function rng(seed) { let s = seed >>> 0; return () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
  function normal(r) { let u = 0; while (u === 0) u = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r()); }
  function curse() {
    const k = +$("#curse-k").value, sy = +$("#curse-s").value, sr = +$("#curse-r").value;
    $("#curse-k-out").textContent = k.toFixed(2) + "×";
    $("#curse-s-out").textContent = sy.toFixed(2);
    $("#curse-r-out").textContent = sr.toFixed(2);
    const r = rng(7), N = 4000, load = 1 / (1 - P.EXPENSE - P.ACTUARY_MARGIN), ps = 4, bonus = Math.log(load) * ps + 0.4;
    let won = 0, prem = 0, loss = 0, priced = 0;
    for (let i = 0; i < N; i++) {
      const truth = Math.exp(0.6 * normal(r));
      const mine = truth * Math.exp(sy * normal(r) - sy * sy / 2) * load * k;
      const best = { u: -ps * Math.log(mine) + bonus - Math.log(-Math.log(r())), me: true };
      for (let j = 0; j < 3; j++) {
        const p = truth * Math.exp(sr * normal(r) - sr * sr / 2) * load;
        const u = -ps * Math.log(p) + bonus - Math.log(-Math.log(r()));
        if (u > best.u) { best.u = u; best.me = false; }
      }
      const out = -ps * Math.log(truth) - Math.log(-Math.log(r()));
      if (best.me && best.u > out) { won++; prem += mine; loss += truth; priced += mine / (load * k) ; }
    }
    const lr = loss / prem, plr = priced / prem, profit = (1 - P.EXPENSE - lr) * 100;
    $("#curse-share").textContent = pct(won / N);
    $("#curse-plr").textContent = pct(plr);
    $("#curse-lr").textContent = pct(lr);
    $("#curse-profit").textContent = (profit >= 0 ? "+" : "") + profit.toFixed(0);
    $("#curse-profit").style.color = profit >= 0 ? "var(--good-text)" : "var(--critical)";
    $("#curse-verdict").textContent = lr > plr * 1.08
      ? `The clients you won are ${pct(lr / plr - 1)} worse than you thought. That gap is the winner's curse.`
      : "Your estimates are good enough, and your prices high enough, that the business you win is roughly what you priced for.";
  }
  ["#curse-k", "#curse-s", "#curse-r"].forEach(s => $(s).addEventListener("input", curse));
  curse();

  // ---------------- toy: claims
  function claims() {
    const p = +$("#cl-p").value, s = +$("#cl-s").value;
    $("#cl-p-out").textContent = pct(p);
    $("#cl-s-out").textContent = pct(s);
    const court = p * (1 + P.INTEREST_LOADING);
    const accepted = s >= P.SETTLE_ACCEPT * p;
    const items = [
      { label: "Pay", value: 1, note: "Pays the covered amount." },
      { label: `Settle at ${pct(s)}`, value: accepted ? s : P.REJECTED_SETTLE_FEE + court,
        note: accepted ? "Accepted: the offer is close enough to the likely award." : "Rejected: goes to court, plus the fee." },
      { label: "Contest", value: P.CONTEST_FEE + court, note: "Court fee, then the claim plus interest if you lose." },
      { label: "Deny", value: P.SUE_PROB_AFTER_DENIAL * p * (1 + P.INTEREST_LOADING + P.BAD_FAITH_LOADING),
        note: "If sued and you lose: claim plus interest plus bad-faith award. Reputation loss not counted here." },
    ];
    const best = Math.min(...items.map(i => i.value));
    items.forEach(i => { i.color = i.value === best ? "--s3" : "--s1"; i.highlight = i.value === best; });
    Charts.bars("#chart-claims", items, { format: v => "$" + v.toFixed(2), max: 2.2, labelName: "Action", valueName: "Expected cost per $1", aria: "expected cost per action" });
    const winner = items.find(i => i.value === best).label;
    $("#cl-verdict").textContent = `Cheapest in expectation: ${winner}. ` +
      (accepted ? "" : `An offer of at least ${pct(P.SETTLE_ACCEPT * p)} would be accepted. `) +
      "The model never sees the true probability, only a noisy murkiness score and the court rulings in the news.";
  }
  ["#cl-p", "#cl-s"].forEach(s => $(s).addEventListener("input", claims));
  claims();

  // ---------------- toy: single-risk rule
  function line() {
    const e = +$("#ln-e").value, a = +$("#ln-a").value, l = +$("#ln-l").value;
    $("#ln-e-out").textContent = "$" + e + "m";
    $("#ln-a-out").textContent = a ? "$" + a + "m" : "no treaty";
    $("#ln-l-out").textContent = "$" + l + "m";
    const net = P.NET_LINE_MAX * e;
    const treaty = a > 0 && l > 0;
    const gross = treaty && a <= net ? net + l : net;
    $("#ln-net").textContent = "$" + net.toFixed(1) + "m";
    $("#ln-gross").textContent = "$" + gross.toFixed(1) + "m";
    const ok = P.SIZE_WORDS.filter((w, i) => P.IDEAL_LIMIT_PER_SIZE * P.SIZE_MULT[i] <= gross + 1e-9);
    $("#ln-sizes").textContent = ok.length ? ok[ok.length - 1] : "none";
    $("#ln-verdict").textContent = !treaty ? "Without reinsurance, every policy's full limit counts against the net line."
      : a > net ? "The treaty attaches above your net line, so it does not help: you would keep more than the rule allows before it starts paying."
      : `The treaty takes the slice from $${a}m to $${a + l}m of each claim, so policies up to $${gross.toFixed(1)}m keep only $${net.toFixed(1)}m net.`;
  }
  ["#ln-e", "#ln-a", "#ln-l"].forEach(s => $(s).addEventListener("input", line));
  line();
})();
